t.script:
document.addEventListener("DOMContentLoaded", function () {
    const form = document.getElementById("lr_form");
    const tipoDocumento = document.getElementById("lr_tipo_documento");
    const numeroDocumento = document.getElementById("lr_numero_documento");
    const nombreConsumidor = document.getElementById("lr_nombre_consumidor");
    const nombreLabel = document.getElementById("lr_nombre_label");
    const domicilioConsumidor = document.getElementById("lr_domicilio_consumidor");
    const docStatus = document.getElementById("lr_doc_status");
    const currency = document.getElementById("lr_currency");
    const currencySymbol = document.getElementById("lr_currency_symbol");
    const canvas = document.getElementById("lr_signature_canvas");
    const signatureData = document.getElementById("lr_signature_data");
    const clearSignature = document.getElementById("lr_clear_signature");
    const submitButton = document.getElementById("lr_submit");
    const ctx = canvas.getContext("2d");

    let drawing = false;
    let hasSignature = false;
    let dniTimer = null;
    let rucTimer = null;

    function resizeCanvas() {
        const ratio = Math.max(window.devicePixelRatio || 1, 1);
        const rect = canvas.getBoundingClientRect();
        const saved = hasSignature ? canvas.toDataURL("image/png") : null;
        canvas.width = Math.floor(rect.width * ratio);
        canvas.height = Math.floor(180 * ratio);
        ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
        ctx.lineWidth = 2;
        ctx.lineCap = "round";
        ctx.lineJoin = "round";
        ctx.strokeStyle = "#17233f";
        if (saved) {
            const image = new Image();
            image.onload = function () {
                ctx.drawImage(image, 0, 0, rect.width, 180);
            };
            image.src = saved;
        }
    }

    function point(event) {
        const rect = canvas.getBoundingClientRect();
        const source = event.touches ? event.touches[0] : event;
        return {x: source.clientX - rect.left, y: source.clientY - rect.top};
    }

    function start(event) {
        event.preventDefault();
        drawing = true;
        hasSignature = true;
        const p = point(event);
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
    }

    function move(event) {
        if (!drawing) return;
        event.preventDefault();
        const p = point(event);
        ctx.lineTo(p.x, p.y);
        ctx.stroke();
    }

    function end(event) {
        if (!drawing) return;
        event.preventDefault();
        drawing = false;
    }

    canvas.addEventListener("mousedown", start);
    canvas.addEventListener("mousemove", move);
    window.addEventListener("mouseup", end);
    canvas.addEventListener("touchstart", start, {passive:false});
    canvas.addEventListener("touchmove", move, {passive:false});
    canvas.addEventListener("touchend", end, {passive:false});

    clearSignature.addEventListener("click", function () {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        hasSignature = false;
        signatureData.value = "";
    });

    window.addEventListener("resize", resizeCanvas);
    resizeCanvas();

    function updateDocumentMode() {
        const type = tipoDocumento.value;
        const isDni = type === "dni";
        const isRuc = type === "ruc";

        numeroDocumento.value = "";
        nombreConsumidor.value = "";
        nombreConsumidor.readOnly = false;
        docStatus.textContent = "";

        if (isDni) {
            numeroDocumento.maxLength = 8;
            numeroDocumento.inputMode = "numeric";
            nombreLabel.innerHTML = 'Nombre completo *';
        } else if (isRuc) {
            numeroDocumento.maxLength = 11;
            numeroDocumento.inputMode = "numeric";
            nombreLabel.innerHTML = 'Razón social *';
        } else {
            numeroDocumento.maxLength = 20;
            numeroDocumento.inputMode = "text";
            nombreLabel.innerHTML = 'Nombre completo *';
        }
    }

    async function lookupDni() {
        if (tipoDocumento.value !== "dni") return;

        const dni = numeroDocumento.value.replace(/\D/g, "");
        numeroDocumento.value = dni;

        if (dni.length !== 8) {
            docStatus.textContent = "";
            nombreConsumidor.readOnly = false;
            return;
        }

        docStatus.textContent = "Consultando...";

        try {
            const response = await fetch("/libro-de-reclamaciones/consultar-dni", {
                method: "POST",
                headers: {"Content-Type": "application/json"},
                body: JSON.stringify({
                    jsonrpc: "2.0",
                    method: "call",
                    params: {numero: dni},
                    id: Date.now()
                })
            });

            const payload = await response.json();
            const result = payload.result || {};

            if (result.ok) {
                nombreConsumidor.value = result.nombre || "";
                nombreConsumidor.readOnly = true;
                docStatus.textContent = "";
            } else {
                nombreConsumidor.readOnly = false;
                docStatus.textContent = "";
            }
        } catch (error) {
            nombreConsumidor.readOnly = false;
            docStatus.textContent = "";
        }
    }

    async function lookupRuc() {
        if (tipoDocumento.value !== "ruc") return;

        const ruc = numeroDocumento.value.replace(/\D/g, "");
        numeroDocumento.value = ruc;

        if (ruc.length !== 11) {
            nombreConsumidor.readOnly = false;
            return;
        }

        try {
            const response = await fetch("/libro-de-reclamaciones/consultar-ruc", {
                method: "POST",
                headers: {"Content-Type": "application/json"},
                body: JSON.stringify({
                    jsonrpc: "2.0",
                    method: "call",
                    params: {numero: ruc},
                    id: Date.now()
                })
            });

            const payload = await response.json();
            const result = payload.result || {};

            if (result.ok) {
                nombreConsumidor.value = result.razon_social || result.nombre || "";
                nombreConsumidor.readOnly = true;

                if (result.direccion) {
                    domicilioConsumidor.value = result.direccion;
                }

                docStatus.textContent = "";
            } else {
                nombreConsumidor.readOnly = false;
                docStatus.textContent = "";
            }
        } catch (error) {
            nombreConsumidor.readOnly = false;
            docStatus.textContent = "";
        }
    }

    tipoDocumento.addEventListener("change", updateDocumentMode);

    numeroDocumento.addEventListener("input", function () {
        if (tipoDocumento.value === "dni") {
            numeroDocumento.value = numeroDocumento.value.replace(/\D/g, "").slice(0, 8);
            clearTimeout(dniTimer);
            dniTimer = setTimeout(lookupDni, 400);
        } else if (tipoDocumento.value === "ruc") {
            numeroDocumento.value = numeroDocumento.value.replace(/\D/g, "").slice(0, 11);
            clearTimeout(rucTimer);
            rucTimer = setTimeout(lookupRuc, 400);
        }
    });

    currency.addEventListener("change", function () {
        currencySymbol.textContent = currency.value === "USD" ? "$" : "S/";
    });

    form.addEventListener("submit", function (event) {
        if (!hasSignature) {
            event.preventDefault();
            alert("Debe registrar su firma antes de enviar la reclamación.");
            canvas.scrollIntoView({behavior:"smooth", block:"center"});
            return;
        }

        signatureData.value = canvas.toDataURL("image/png");
        submitButton.disabled = true;
        submitButton.textContent = "Registrando...";
    });
});
